def _cmd_log_query(
    log_path, start_token, end_token, kind_token, applied_token,
    cursor_token, count_token, max_log_bytes, max_output_bytes,
):
    # START/END 为 * 或任意长度非负整数（按数学整数比较）；均非 * 时
    # START≤END；APPLIED 取 */true/false；KIND 取 * 或已知七类；
    # CURSOR/COUNT 完全沿用 log-page；格式非法按 usage 退出 2（打开文件前）
    if _FILTER_BOUND_RE.fullmatch(start_token) is None:
        _fail("usage")
        return 2
    if _FILTER_BOUND_RE.fullmatch(end_token) is None:
        _fail("usage")
        return 2
    if kind_token != "*" and kind_token not in _QUERY_KINDS:
        _fail("usage")
        return 2
    if applied_token not in ("*", "true", "false"):
        _fail("usage")
        return 2
    if _PAGE_CURSOR_RE.fullmatch(cursor_token) is None:
        _fail("usage")
        return 2
    if _LIMIT_RE.fullmatch(count_token) is None:
        _fail("usage")
        return 2
    start = None if start_token == "*" else _limit_value(start_token)
    end = None if end_token == "*" else _limit_value(end_token)
    if start is not None and end is not None and start > end:
        _fail("usage")
        return 2
    want_applied = None if applied_token == "*" else (applied_token == "true")
    want_kind = None if kind_token == "*" else kind_token
    count = _limit_value(count_token)
    try:
        with open(log_path, "rb") as handle:
            # 读取与字节边界完全沿用 log-filter：分块至多 65536 字节，
            # 输入上限按原始字节计，等于上限合法
            log_raw = _read_limited(handle, max_log_bytes)
    except OSError:
        _fail("file_not_found")
        return 3
    if log_raw is None:
        _fail("log_limit")
        return 5
    try:
        # 与 log-page 同一套静态校验与内部摘要核对：顶层/记录键序与
        # 字段类型、config/event 规范键序、event 已知键形、内部 sha256；
        # 不校验配置语义、不重演事件
        log = parse_json(log_raw)
        _validate_log_shape(log)
        source_sha = log["sha256"]
        if hashlib.sha256(_log_prefix_bytes(log)).hexdigest() != source_sha:
            raise InvalidInput("bad log sha256")
        records = log["records"]
        total = len(records)
        if cursor_token == "*":
            # * 从原 LOG records 下标 0 开始
            offset = 0
        else:
            cursor_sha, offset_token = cursor_token.split(":", 1)
            # 游标摘要须等于 LOG.sha256 且 offset≤记录数（沿用 log-page）
            if cursor_sha != source_sha:
                raise InvalidInput("bad cursor sha256")
            offset = _limit_value(offset_token)
            if offset > total:
                raise InvalidInput("bad cursor offset")
        # 从 offset 起扫描，时间闭区间、kind、applied 合取，原序原样取
        # 至多 COUNT 项；matched 记 (原始下标, 原样记录)
        matched = []
        i = offset
        while i < total and len(matched) < count:
            record = records[i]
            if start is None or record["t"] >= start:
                if end is None or record["t"] <= end:
                    if want_kind is None or _event_kind(
                        record["event"]
                    ) == want_kind:
                        if want_applied is None or record[
                            "applied"
                        ] is want_applied:
                            matched.append((i, record))
            i += 1
        # 已收满 COUNT 项且其后仍有匹配项时 next 为 LOG.sha256:<最后返回
        # 项的下一原始下标>（最后匹配项下标 +1）；否则 null。向前只判定
        # 是否仍有匹配，游标本身指最后返回项的紧后原始下标（同 log-page
        # 的“下一下标”，命名空间为原 LOG records 下标）
        nxt = None
        if len(matched) == count:
            last_index = matched[-1][0]
            j = last_index + 1
            while j < total:
                candidate = records[j]
                if (
                    (start is None or candidate["t"] >= start)
                    and (end is None or candidate["t"] <= end)
                    and (
                        want_kind is None
                        or _event_kind(candidate["event"]) == want_kind
                    )
                    and (
                        want_applied is None
                        or candidate["applied"] is want_applied
                    )
                ):
                    nxt = source_sha + ":" + str(last_index + 1)
                    break
                j += 1
        doc = {
            "schema": RECORD_SCHEMA,
            "source_sha256": source_sha,
            # query 固定四键序：输入 * 写 null，其余整数、整数、字符串、布尔
            "query": {
                "start": start,
                "end": end,
                "kind": want_kind,
                "applied": want_applied,
            },
            "records": [record for _, record in matched],
            "next": nxt,
        }
        doc["sha256"] = hashlib.sha256(_query_prefix_bytes(doc)).hexdigest()
        payload = _query_bytes(doc)
    except InvalidInput:
        _fail("invalid_input")
        return 4
    # 输出上界（含末尾 LF）在写出前判定；等于上限合法，失败 stdout 为空
    if len(payload) > max_output_bytes:
        _fail("output_limit")
        return 5
    sys.stdout.buffer.write(payload)
    return 0


CONFIG_DIFF_MAX_INPUT_BYTES = 1024 * 1024


def _json_pointer_token(token):
    """RFC6901 reference token 转义：~ 编码为 ~0，/ 编码为 ~1。"""
    return token.replace("~", "~0").replace("/", "~1")


def _diff_collect(old, new, path, changes):
    """按键序无关契约收集 OLD、NEW 的差异项到 changes。

    对象递归，键按 Unicode 码点升序深度优先；数组整体比较且顺序敏感，
    整组不同仅出一项；标量按 JSON 类型与值比较。path 为 RFC6901 JSON
    Pointer（根为 ""）。仅不同的数组或标量（及缺失对象键）生成项。
    """
    if isinstance(old, dict) and isinstance(new, dict):
        for key in sorted(set(old) | set(new)):
            child = path + "/" + _json_pointer_token(key)
            if key in old and key in new:
                _diff_collect(old[key], new[key], child, changes)
            elif key in old:
                # 仅旧侧存在；合法 port-security 配置各层键集固定，不会到达
                changes.append(
                    {"path": child, "before": _canonical(old[key]),
                     "after": None}
                )
            else:
                changes.append(
                    {"path": child, "before": None,
                     "after": _canonical(new[key])}
                )
        return
    # 两数组整体（顺序敏感）、两标量（JSON 类型+值）或类别不一致：
    # 不同即整值一项，前后值按同一规则规范化
    if not _json_equal(old, new):
        changes.append(
            {"path": path, "before": _canonical(old),
             "after": _canonical(new)}
        )


def _diff_size(value):
    """工作量公式的 S：标量 1；数组 1+各元素 S 之和；
    对象 1+键数+各值 S 之和。"""
    if isinstance(value, dict):
        return 1 + len(value) + sum(_diff_size(item) for item in value.values())
    if isinstance(value, list):
        return 1 + sum(_diff_size(item) for item in value)
    return 1


def _diff_size_charge(value, remaining):
    """S 的计费版：从剩余额度扣减 S(value)，返回扣后额度（耗尽为 0）。

    对象先计 1+键数，再按键的 Unicode 码点升序逐值计费；数组先计 1，
    再按元素序逐项计费；标量计 1。累计首次超过剩余额度即抛
    DiffWorkLimit，不再访问后续元素或键值；额度足够时累计恰为
    S(value)，与 _diff_size 一致。
    """
    if isinstance(value, dict):
        cost = 1 + len(value)
        if cost > remaining:
            raise DiffWorkLimit
        remaining -= cost
        for key in sorted(value):
            remaining = _diff_size_charge(value[key], remaining)
        return remaining
    if isinstance(value, list):
        if remaining < 1:
            raise DiffWorkLimit
        remaining -= 1
        for item in value:
            remaining = _diff_size_charge(item, remaining)
        return remaining
    if remaining < 1:
        raise DiffWorkLimit
    return remaining - 1


def _diff_work(old, new, remaining):
    """按工作量公式无副作用预演 D，返回剩余额度（耗尽为 0）。

    两值均为对象时计 1+并集键数，共有键递归计 D，单侧键计该侧 S；
    其余（含数组整体）计 1+S(旧值)+S(新值)。键按 Unicode 码点升序
    累计，递归逐层传递剩余额度；等于上限合法，首次超过即抛
    DiffWorkLimit，此后不再访问后续元素、键值或单侧子树。
    """
    if isinstance(old, dict) and isinstance(new, dict):
        cost = 1 + len(set(old) | set(new))
        if cost > remaining:
            raise DiffWorkLimit
        remaining -= cost
        for key in sorted(set(old) | set(new)):
            if key in old and key in new:
                remaining = _diff_work(old[key], new[key], remaining)
            else:
                remaining = _diff_size_charge(
                    old[key] if key in old else new[key], remaining
                )
        return remaining
    if remaining < 1:
        raise DiffWorkLimit
    remaining -= 1
    remaining = _diff_size_charge(old, remaining)
    return _diff_size_charge(new, remaining)


def _cmd_config_diff(
    old_path,
    new_path,
    max_diff_work=DEFAULT_MAX_DIFF_WORK,
    max_input_bytes=CONFIG_DIFF_MAX_INPUT_BYTES,
    max_output_bytes=None,
